insert into cases (id,title,category,risk_label,content,source,tags) values
('b1ab57c7-2bc1-4e64-852f-08519226e712','ETC到期失效短信钓鱼骗局','ETC','诈骗','收到短信提示ETC即将到期失效，点击链接完成续约，页面为伪造网站，输入银行卡信息直接被盗刷。','反诈公开案例',ARRAY['ETC到期', '续约短信', '伪造网站']::text[]),
('2288206b-0ea4-49d2-a467-bd332ad5634b','ETC异常扣费短信钓鱼诈骗','ETC','诈骗','发送ETC扣费异常、账户冻结短信，附带钓鱼短链接，诱导用户点击链接填写身份证、银行卡，盗取个人财产。','反诈公开案例',ARRAY['ETC', '短信钓鱼', '异常扣费', '短链接']::text[]),
('425a5647-6e88-4ce2-a5ad-ab61c8a116f1','ETC异常扣费诈骗','ETC','诈骗','收到短信提示ETC账户冻结/异常扣费，点击链接完成解冻，页面要求输入身份证银行卡。','反诈中心',ARRAY['ETC', '短信链接', '解冻']::text[]),
('912cb46e-feeb-4153-bdfb-5da53e9c60f7','兼职刷单小额返利诱导大额垫付','刷单','诈骗','骗子在社交软件发布刷单兼职广告，先用小额任务返还佣金建立信任，随后下发大额连单任务，要求受害人不断充值垫付，最后以任务未完成、账户冻结为由拒绝返还本金并将受害人拉黑。','反诈知识库种子',ARRAY['刷单', '垫付', '连单', '返利']::text[]),
('e0d4bebf-7640-4702-8908-6a02249a4c27','冒充ETC客服，办理退费返还诈骗','ETC','诈骗','骗子声称ETC多扣通行费，可以办理退费，引导提供银行卡和验证码，借机盗刷账户余额。','反诈公开案例',ARRAY['ETC退费', '多扣通行费', '验证码泄露']::text[]),
('e49c9ea4-d356-408c-860b-7c76b6e96521','冒充ETC工作人员要求升级账户','ETC','诈骗','冒充ETC客服打电话，告知ETC需要升级，引导添加微信或者访问非官方网站，索要验证码转账。','反诈公开案例',ARRAY['ETC升级', '冒充工作人员', '电话诈骗']::text[]),
('70d627fd-5b5e-4a82-80bd-1ba9d533688c','冒充公安发送伪造逮捕证实施恐吓诈骗','冒充公检法','诈骗','冒充公安，通过聊天软件发送伪造逮捕证、拘留文书，恐吓受害人不能告诉家人，要求转账资金自清。','反诈公开案例',ARRAY['伪造逮捕证', '恐吓施压', '资金自清']::text[]),
('c098158c-e1f2-4c85-ad05-68cee8eb0ce5','冒充公安称涉嫌犯罪要求资金清查','冒充公检法','诈骗','骗子冒充公安机关或检察院工作人员来电，谎称受害人涉嫌洗钱等犯罪，出示伪造的法律文书制造恐慌，要求将资金转入所谓安全监管账户接受清查，并叮嘱不得告知家人，转账后资金无法追回。','反诈知识库种子',ARRAY['冒充公检法', '资金清查', '安全账户', '伪造文书']::text[]),
('439443e8-aab0-4c63-95d7-14a45f4196a8','冒充公检法涉嫌犯罪要求资金清查','冒充公检法','诈骗','冒充警察、检察院来电，谎称个人涉嫌洗钱犯罪，出示伪造法律文书，要求把钱转入安全监管账户做资金清查，实际是诈骗转账。','反诈公开案例',ARRAY['冒充公检法', '洗钱', '安全账户', '电话恐吓']::text[]),
('3fadbedb-57b1-44e4-aacb-f23c59553955','冒充出入境公安，名下银行卡涉案诈骗','冒充公检法','诈骗','冒充出入境公安来电，声称受害人名下银行卡涉嫌犯罪，要求隔离审查，诱导资金转入所谓监管账户。','反诈公开案例',ARRAY['出入境公安', '银行卡涉案', '隔离审查']::text[]),
('e7d9838d-8a4a-4446-9216-79a71008ecb2','冒充品牌公众号抽奖中奖诈骗','中奖','诈骗','不法分子仿冒知名品牌公众号推送中奖通知，谎称用户抽中手机或现金大奖，要求先行支付运费、税费、保证金后才能领奖，转账完成后对方立即拉黑，奖品始终不会发放。','反诈知识库种子',ARRAY['中奖', '仿冒公众号', '运费税费', '保证金']::text[]),
('66e273c2-ed42-4e23-bc8e-c1305d5fc755','冒充售后客服，以换货为由索要验证码','冒充客服','诈骗','冒充商品售后客服，说商品损坏可以换货，需要短信验证码核验身份，拿到验证码直接盗刷账户。','反诈公开案例',ARRAY['换货售后', '短信验证码', '身份核验']::text[]),
('23fcf0e4-fcb0-4203-a743-9a7efaed08cf','冒充培训机构办理退费退款','退费','诈骗','冒充培训机构工作人员，说机构倒闭可以办理学费退费，但是要先缴纳手续费，诱导转账，没有任何退款到账。','反诈公开案例',ARRAY['教育退费', '培训机构', '手续费']::text[]),
('2c793ddf-d738-4031-853e-389fc664a794','冒充客服谎称订单涉嫌违法需要处理','冒充客服','诈骗','冒充平台客服来电，称受害人购买商品涉嫌违禁品，需要配合资金核验，诱导转账到所谓安全账户。','反诈公开案例',ARRAY['订单涉嫌违法', '资金核验', '冒充平台客服']::text[]),
('3d97c575-4bdb-4051-9c83-462104b7b86d','冒充平台KYC身份核验冻结账户','KYC','诈骗','冒充互联网平台，通知用户账号KYC身份信息不全，账户即将冻结，引导跳转第三方页面，提交身份证、人脸、银行卡信息。','反诈公开案例',ARRAY['KYC', '身份核验', '账号冻结', '信息泄露']::text[]),
('5cedb846-cd1d-412b-acef-0c5a112b206f','冒充平台客服谎称会员扣费可退款','冒充客服','诈骗','冒充视频平台客服，告知用户误开通年度会员，不关闭会自动扣费，引导点击陌生链接操作退款，盗取账号资金。','反诈公开案例',ARRAY['会员扣费', '误开通', '虚假退款链接']::text[]),
('ac6c13ec-0625-479f-9778-bdcffeb913f0','冒充快递员谎称快递丢失主动理赔','快递理赔','诈骗','骗子冒充快递公司工作人员，电话或短信告知受害人的包裹在运输中丢失或损坏，主动提出高额理赔，随后发送仿冒链接或要求提供银行卡号、短信验证码，进而盗刷受害人账户资金。','反诈知识库种子',ARRAY['快递理赔', '包裹丢失', '钓鱼链接', '验证码']::text[]),
('9b0f4025-a29a-475b-95a1-d0b05aa07d01','冒充快递客服，谎称包裹含有违禁品','快递理赔','诈骗','冒充快递工作人员来电，说你的快递查出违禁物品，要配合理赔调查，诱导转账做资金清查。','反诈公开案例',ARRAY['快递违禁品', '调查理赔', '冒充快递']::text[]),
('40bcbe85-de97-4223-9103-b46970ef915a','冒充快递客服谎称包裹丢失理赔','快递理赔','诈骗','冒充快递公司客服，告知用户快递丢失，主动提出高额理赔，引导点击陌生链接、提供银行卡信息，实施盗刷。','反诈公开案例',ARRAY['快递丢失', '理赔', '冒充快递']::text[]),
('aaf70802-2678-4157-9b52-43457625ddde','冒充支付平台KYC补全信息诈骗','KYC','诈骗','短信通知支付账号KYC信息过期，点击链接补全人脸和银行卡资料，钓鱼页面收集个人敏感信息。','反诈公开案例',ARRAY['KYC过期', '支付账号', '人脸采集钓鱼']::text[]),
('5a5b7c41-ed41-4877-a7e2-e1c278f3e67e','冒充法院，谎称涉嫌传票犯罪，视频笔录诈骗','冒充公检法','诈骗','冒充法院工作人员，说收到法院传票涉嫌犯罪，开启视频通话做笔录，恐吓受害人转移资金到安全账户。','反诈公开案例',ARRAY['法院传票', '视频笔录', '冒充法院']::text[]),
('5535ef26-36ba-4787-bee1-5d280ce7ac1c','冒充海外海淘平台客服退款诈骗','冒充客服','诈骗','冒充海淘跨境购物平台客服，说海关扣货，要办理退款补偿，发送境外钓鱼链接，套取银行卡信息。','反诈公开案例',ARRAY['海淘', '海关扣货', '境外钓鱼链接']::text[]),
('f7112536-4747-4950-a570-0ccb489a9c22','冒充电商客服共享屏幕盗刷资金','冒充客服','诈骗','冒充网购客服打电话说订单异常需要退款，诱导受害人开启手机共享屏幕，远程查看银行卡、验证码，直接盗刷银行卡余额。','反诈公开案例',ARRAY['共享屏幕', '远程操控', '订单异常']::text[]),
('afa69073-74d1-42aa-aab8-6cc4ca0cd972','冒充电商客服谎称订单异常办理退款','冒充客服','诈骗','骗子冒充电商平台客服，准确报出受害人订单信息后谎称订单异常需要退款，诱导点击陌生链接填写银行卡与验证码，或要求开启屏幕共享远程操作，最终盗取账户资金。','反诈知识库种子',ARRAY['冒充客服', '订单异常', '退款', '屏幕共享']::text[]),
('e99416ec-5940-4034-b6e9-49f3a48da938','冒充网课机构，退费需要缴纳保证金诈骗','退费','诈骗','冒充网课机构客服，通知课程可以退费，要求先缴纳保证金，保证金会和学费一起退回，转账之后直接失联。','反诈公开案例',ARRAY['网课退费', '退费保证金', '课程退款']::text[]),
('d6beb279-e540-45ff-80ad-65ef8ef6853b','冒充网购客服谎称商品丢失理赔','冒充客服','诈骗','骗子获取购物记录，冒充平台客服，谎称包裹丢失，主动提出高额理赔，诱导受害人提供银行卡号和短信验证码。','反诈公开案例',ARRAY['商品丢失', '理赔退款', '冒充电商']::text[]),
('3748862c-eb0d-43d2-9548-7e6fe821b1cd','冒充网购客服谎称商品质量问题退款','冒充客服','诈骗','骗子获取网购订单信息，冒充平台客服，说商品存在质量问题要给用户理赔退款，发送虚假链接，诱导填写银行卡、验证码，盗取账户资金。','反诈公开案例',ARRAY['退款理赔', '冒充客服', '验证码', '虚假链接']::text[]),
('e8001cd0-113d-4021-8f1c-07754d39912a','冒充网贷客服，征信洗白贷款诈骗','贷款','诈骗','声称可以帮助洗白不良征信，办理低息大额贷款，需要缴纳服务费、征信修复费，交钱之后贷款永远下不来。','反诈公开案例',ARRAY['征信洗白', '网贷服务费', '修复征信']::text[]),
('f5340657-837a-4f3d-9ba8-a3fd8237353d','冒充证券平台KYC身份更新诈骗','KYC','诈骗','冒充股票证券平台，通知KYC身份资料过期，需要跳转外部网页更新身份，套取银行卡和交易密码。','反诈公开案例',ARRAY['证券KYC', '身份更新', '交易密码泄露']::text[]),
('44cb14a0-05ab-4f90-a34d-e7f375f9dfe5','冒充银行KYC身份核验，要求转账核验流水','KYC','诈骗','冒充银行通知KYC身份核验不通过，账户会被冻结，要求转账到指定账户做流水核验，转账之后资金被骗走。','反诈公开案例',ARRAY['银行KYC', '流水核验', '账户冻结威胁']::text[]),
('e0a68c2c-ba89-40c1-8d91-f92b401ce853','冒充银行贷款专员，验资转账诈骗','贷款','诈骗','冒充银行信贷工作人员，说可以办理大额信用贷，要求往银行卡转账做资金验资，验资资金直接被转走。','反诈公开案例',ARRAY['银行信贷', '资金验资', '贷款专员冒充']::text[]),
('aeee1fb6-2b13-4b3d-931a-717e26064b98','刷单任务卡单需要解冻资金诈骗','刷单','诈骗','受害人做完刷单任务，骗子谎称任务卡单，账户异常，需要转账缴纳解冻金才能把本金佣金全部取出，交完继续编造理由要钱。','反诈公开案例',ARRAY['卡单', '解冻金', '刷单提现失败']::text[]),
('f6796554-6f23-49a2-b5ce-e817a36bb76f','刷单返利，小额返利诱导大额投入','刷单','诈骗','骗子通过社交软件发布刷单兼职广告，先给小额任务返还佣金获取信任，之后下发大额连单任务，要求不断充值垫付，之后以任务未完成、冻结资金为由拒绝返还本金与佣金，最后拉黑失联。','反诈公开案例',ARRAY['刷单', '兼职', '垫付', '返利']::text[]),
('e4a5d9c5-63a4-4418-98a2-b8b55cae62df','刷单返利冒充客服办理提现诈骗','刷单','诈骗','刷单平台拒绝提现，冒充平台客服联系受害人，声称缴纳手续费即可开通提现权限，转账之后直接失联。','反诈公开案例',ARRAY['冒充客服', '提现手续费', '刷单平台']::text[]),
('a1dfeb10-797e-4597-b21d-68ad571e5b7f','小红书评论点赞刷单骗局','刷单','诈骗','在小红书私信招募点赞评论员，简单任务给小额红包，之后跳转外部APP做刷单任务，诱导银行卡转账垫资。','反诈公开案例',ARRAY['小红书', '点赞任务', '外部APP']::text[]),
('00e3ae4b-606e-4986-b974-5416c899b87f','微信群刷单抢红包陷阱','刷单','诈骗','受害人被拉入微信群，群内发红包吸引加入，诱导下载内部刷单APP，前期小额提现成功，后续组合大单要求连续转账，以操作失误冻结账号拒绝回款。','反诈公开案例',ARRAY['微信群刷单', '连单任务', '账号冻结']::text[]),
('e5320a26-27e8-425b-8e41-e5ad6e23cf54','快递短信带钓鱼链接理赔诈骗','快递理赔','诈骗','收到短信，你的快递损毁点击链接领取理赔金，点开是钓鱼网页，输入银行卡密码就被盗刷。','反诈公开案例',ARRAY['快递短信', '钓鱼短链接', '损毁理赔']::text[]),
('9ed3825a-de85-41a0-8d96-8a2f95c7e079','快递破损理赔，诱导下载陌生APP诈骗','快递理赔','诈骗','骗子冒充快递，说包裹运输破损，要给理赔，不让用官方APP，诱导下载第三方陌生软件办理理赔，窃取手机信息。','反诈公开案例',ARRAY['包裹破损', '第三方APP', '快递理赔']::text[]),
('8e7844c5-7438-46ff-8362-26e168c92977','抖音点赞刷单兼职骗局','刷单','诈骗','声称点赞关注短视频即可赚钱，先做简单任务发小红包，后续引导下载陌生APP做刷单任务，需要个人转账垫资，垫资越大损失越高。','反诈公开案例',ARRAY['点赞刷单', '短视频兼职', '陌生APP']::text[]),
('5c2f3cb8-3b5d-4ff3-81b1-74b80f751aaa','招聘兼职刷信誉购物刷单诈骗','刷单','诈骗','网上发布招聘刷信誉兼职，宣称足不出户日赚几百，第一二单返还佣金，后面要求多单联做，不断加大垫付金额，完成后直接拉黑。','反诈公开案例',ARRAY['刷信誉', '网上兼职', '垫付本金']::text[]),
('28562823-b03d-46ea-a2fb-ecb5812939cb','杀猪盘以家庭困难借钱周转实施诈骗','杀猪盘','诈骗','网上恋爱交往一段时间，编造家人重病、生意周转等理由，多次向受害人借钱，拿到钱款之后直接拉黑消失。','反诈公开案例',ARRAY['网恋借钱', '家庭变故', '情感诈骗']::text[]),
('0172fb5c-e7e4-435f-bb16-a7a5096414b0','杀猪盘伪装高净值人士诱导虚拟币投资','杀猪盘','诈骗','网上伪装成功人士谈恋爱，取得信任之后，介绍内部虚拟币交易平台，受害人投入大量资金，平台后台人为操控盈亏。','反诈公开案例',ARRAY['虚拟币', '网恋杀猪盘', '虚假交易平台']::text[]),
('6ebe178d-5400-4de4-a739-d1aaff3f3fe6','杀猪盘网恋诱导虚假投资平台','杀猪盘','诈骗','社交软件伪装异性交友网恋，建立情感信任之后，诱导进入私设虚假投资网站，前期小额可以提现，大额投入之后平台无法登录，资金全部被骗走。','反诈公开案例',ARRAY['网恋', '虚假投资', '杀猪盘', '交友软件']::text[]),
('2c091ce8-a283-48f2-9687-440b27eb7296','杀猪盘诱导受害人帮自己操作投资账号','杀猪盘','诈骗','网恋对象说自己不方便操作投资，把账号密码发给受害人代为操作，让受害人看到高额盈利，引诱受害人自己注册充值。','反诈公开案例',ARRAY['代为操作账号', '虚假盈利诱导', '杀猪盘套路']::text[]),
('0a16d666-0c94-47f6-aded-09eef5bf0a25','校园培训退费诈骗','退费','诈骗','针对大学生，声称网课培训班可以全额退费，添加QQ群，引导下载APP，以验资名义让学生转账。','反诈公开案例',ARRAY['大学生', '网课退费', 'QQ群']::text[]),
('ac8f87da-a393-4c3d-add0-39044954736c','校园学生QQ群刷单兼职诈骗','刷单','诈骗','骗子潜入高校QQ群发布刷单兼职，瞄准学生零花钱少想赚外快心理，诱导学生用生活费垫付刷单，最后卷钱跑路。','反诈公开案例',ARRAY['大学生', 'QQ群兼职', '生活费垫付']::text[]),
('ee35469e-52cc-4a17-94f4-8ab9163ee095','校园虚假网贷，学生缴纳会员费才能放款','贷款','诈骗','面向大学生宣传低息校园贷，申请贷款时，告知需要开通高级会员才能放款，学生缴纳会员费后，平台失联。','反诈公开案例',ARRAY['校园贷', '会员费', '大学生贷款诈骗']::text[]),
('192d9e36-bbb5-4e7f-9838-3bdd504c8ac2','游戏内弹窗中奖，诱导转账领奖诈骗','中奖','诈骗','游戏聊天窗口弹出恭喜中奖，发送QQ联系领奖客服，客服以领奖手续费、激活费为由不断要钱。','反诈公开案例',ARRAY['游戏中奖弹窗', '领奖客服', '激活费用']::text[]),
('08f8d897-32f1-46cb-8448-f648a8a6cb11','电商店铺好评刷单返利陷阱','刷单','诈骗','宣称给淘宝店铺写好评拿佣金，初期小额返利，后续引导脱离平台私下转账垫付，不经过电商官方交易。','反诈公开案例',ARRAY['好评刷单', '脱离平台', '私下转账']::text[]),
('f8a207db-b9c7-40db-916a-1fe3c3d425bf','直播平台关注刷数据刷单诈骗','刷单','诈骗','宣称帮直播间涨粉刷数据可以赚钱，先小额结算，之后要求大额充值解锁高级任务，充值之后无法提现。','反诈公开案例',ARRAY['直播间刷数据', '涨粉任务', '解锁高级任务']::text[]),
('09697afa-a431-45e4-a112-7860a01bddbe','短信通知中奖，需要先交税费才能领奖','中奖','诈骗','短信告知用户中大奖，奖品为手机、现金等，但是需要先缴纳个税、保证金、手续费，转账之后对方直接消失。','反诈公开案例',ARRAY['中奖', '手续费', '保证金', '领奖']::text[]),
('66eb7075-2819-4ff1-9206-862d3a093a4e','短视频弹窗中奖，填写信息缴纳领奖保证金','中奖','诈骗','刷短视频弹出中奖弹窗，提示抽中手机平板，点击跳转网页，要求缴纳保证金才能领取奖品，无任何实物发放。','反诈公开案例',ARRAY['短视频弹窗', '中奖弹窗', '领奖保证金']::text[]),
('ce7a3c01-9588-492d-b2ca-1d520a572ff7','社交软件相亲杀猪盘，诱导博彩平台充值','杀猪盘','诈骗','相亲交友软件认识对象，确立恋爱关系，透露自己掌握博彩平台漏洞，带受害人一起赚钱，充值之后无法提现。','反诈公开案例',ARRAY['相亲软件', '博彩漏洞', '杀猪盘博彩']::text[]),
('3ed29dc1-a3d0-4c7d-8a4e-92ce5ca76d52','网络低息贷款，先交保证金解冻金','贷款','诈骗','广告宣传低息无抵押网贷，提交资料之后，骗子说银行卡号错误账户冻结，要求缴纳解冻金、保证金，交完依旧不放款。','反诈公开案例',ARRAY['网贷', '解冻金', '保证金', '银行卡错误']::text[]),
('34b29134-c45b-429d-9855-66a246a09806','网贷审批失败，缴纳刷流水费用诈骗','贷款','诈骗','网贷申请提示审批不通过，骗子说帮忙刷流水提高通过率，要求受害人转账刷流水，刷完直接失联。','反诈公开案例',ARRAY['贷款刷流水', '审批失败', '刷流水服务费']::text[])
